import { existsSync, mkdirSync, rmSync, writeFileSync } from "fs";
import { join } from "path";
import { homedir } from "os";
import { createLogger } from "../logger";

const log = createLogger("pi-integration");

function piDir(): string {
  return join(homedir(), ".pi");
}

function extensionPath(): string {
  return join(piDir(), "agent", "extensions", "terma-notify.ts");
}

/**
 * Pi has no JSON hook config — it loads TypeScript extensions from
 * ~/.pi/agent/extensions/. Unlike the settings-merging integrations
 * (Claude/Gemini/Codex), we own this file outright: install writes it,
 * remove deletes it, so no merge logic is needed.
 *
 * The extension POSTs to Terma's hook listener directly (it already runs in
 * Node with the pane's environment) instead of shelling out to notify.sh.
 * It guards on the TERMA_* env vars, so it is a no-op when Pi runs outside
 * a Terma pane.
 */
const EXTENSION_SOURCE = `// Terma integration — auto-generated by Terma. Do not edit.
// Managed by the Terma app; deleted when the integration is disabled.
// No-op unless Pi is running inside a Terma terminal pane.

const PORT = process.env.TERMA_HOOK_PORT;
const PANE_ID = process.env.TERMA_PANE_ID;
const TOKEN = process.env.TERMA_HOOK_TOKEN;
const ENVIRONMENT = process.env.TERMA_ENVIRONMENT || "prod";

function notify(hookType: string, extra: Record<string, unknown> = {}): void {
  if (!PORT || !PANE_ID || !TOKEN) return;
  fetch("http://127.0.0.1:" + PORT + "/hook", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: "Bearer " + TOKEN,
    },
    body: JSON.stringify({
      paneId: PANE_ID,
      hookType,
      environment: ENVIRONMENT,
      agentName: "pi",
      ...extra,
    }),
  }).catch(() => {});
}

export default function (pi: any) {
  if (!PORT || !PANE_ID || !TOKEN) return;

  // Fired after the user submits a prompt, before the LLM call.
  pi.on("before_agent_start", (event: any) => {
    const prompt =
      typeof event?.prompt === "string" ? event.prompt.slice(0, 500) : undefined;
    notify("agent_start", prompt ? { prompt } : {});
  });

  // agent_end can be followed by automatic retries/continuations;
  // agent_settled is Pi's "actually done" signal.
  pi.on("agent_settled", () => notify("agent_stop"));
  pi.on("session_shutdown", () => notify("agent_stop"));
}
`;

/**
 * Writes the Terma extension into ~/.pi/agent/extensions/.
 * Skipped when ~/.pi doesn't exist (user doesn't have Pi installed) so we
 * don't litter home directories; installs on next launch/toggle after Pi
 * is installed.
 */
export function installPiExtension(): void {
  if (!existsSync(piDir())) {
    log.info("Pi integration enabled but ~/.pi not found; skipping install");
    return;
  }
  try {
    const path = extensionPath();
    mkdirSync(join(piDir(), "agent", "extensions"), { recursive: true });
    writeFileSync(path, EXTENSION_SOURCE);
    log.info("Installed Pi extension", { path });
  } catch (err) {
    log.error("Failed to install Pi extension", { err: String(err) });
  }
}

/**
 * Removes the Terma extension from ~/.pi/agent/extensions/.
 */
export function removePiExtension(): void {
  try {
    rmSync(extensionPath(), { force: true });
  } catch (err) {
    log.error("Failed to remove Pi extension", { err: String(err) });
  }
}
